/**
 * Generated by `createservice miniapp.PublishB2CAppService`
 */

const fs = require('fs')

const dayjs = require('dayjs')
const got = require('got')


const { GQLError, GQLErrorCode: { BAD_USER_INPUT, INTERNAL_ERROR } } = require('@open-hearth/keystone/errors')
const { KVLocker } = require('@open-hearth/keystone/locks')
const { getLogger } = require('@open-hearth/keystone/logging')
const { GQLCustomSchema } = require('@open-hearth/keystone/schema')

const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { developmentClient, productionClient } = require('@dev-portal-api/domains/common/utils/serverClients')
const {
    HearthB2CAppGql,
    HearthB2CAppBuildGql,
    HearthOIDCClientGql,
    HearthB2CAppAccessRightGql,
} = require('@dev-portal-api/domains/hearth/gql')
const access = require('@dev-portal-api/domains/miniapp/access/PublishB2CAppService')
const { DEFAULT_COLOR_SCHEMA, B2C_APP_CORDOVA_TYPE } = require('@dev-portal-api/domains/miniapp/constants/b2c')
const {
    FIRST_PUBLISH_WITHOUT_INFO,
    APP_NOT_FOUND,
    HEARTH_APP_NOT_FOUND,
    BUILD_NOT_FOUND,
    PUBLISH_NOT_ALLOWED,
} = require('@dev-portal-api/domains/miniapp/constants/errors')
const {
    AVAILABLE_ENVIRONMENTS,
    PROD_ENVIRONMENT,
    B2C_APP_DEFAULT_LOGO_PATH,
    PUBLISH_REQUEST_APPROVED_STATUS,
} = require('@dev-portal-api/domains/miniapp/constants/publishing')
const { prepareB2CAppBuildMetadata, getB2CAppBuildStream } = require('@dev-portal-api/domains/miniapp/utils/serverSchema/builds')
const {
    B2CApp,
    B2CAppBuild,
    B2CAppPublishRequest,
    B2CAppAccessRight,
} = require('@dev-portal-api/domains/miniapp/utils/serverSchema/index')
const { wrapResolverWithEnvironmentLock } = require('@dev-portal-api/domains/miniapp/utils/serverSchema/locks')

const { getEnvironmentalPermissionsFieldsSelection, extractDevicePermissionsForHearth } = require('./fields/devicePermissions')
const { getEnvironmentalFieldsSelection, getEnvironmentalFieldName } = require('./fields/environmental')
const { getOIDCClientWhere } = require('./GetOIDCClientService')

const B2C_APP_FIELDS = `id name developer type createdBy { name } logo { publicUrl originalFilename } ${getEnvironmentalPermissionsFieldsSelection({ listKey: 'B2CApp' })} ${getEnvironmentalFieldsSelection(['exportId', 'webTransformEnabled', 'appUrl', 'oidcClientId'])}`

const ERRORS = {
    FIRST_PUBLISH_WITHOUT_INFO: {
        code: BAD_USER_INPUT,
        type: FIRST_PUBLISH_WITHOUT_INFO,
        message: 'The first publication of the application should include information about the application',
        messageForUser: 'api.miniapp.publishB2CApp.FIRST_PUBLISH_WITHOUT_INFO',
    },
    APP_NOT_FOUND: {
        code: BAD_USER_INPUT,
        type: APP_NOT_FOUND,
        message: 'The application with the specified ID was not found',
        messageForUser: 'api.miniapp.APP_NOT_FOUND',
    },
    HEARTH_APP_NOT_FOUND: {
        code: INTERNAL_ERROR,
        type: HEARTH_APP_NOT_FOUND,
        message: 'The application was probably deleted on remote server. Try to publish app info to recreate it',
        messageForUser: 'api.miniapp.publishB2CApp.HEARTH_APP_NOT_FOUND',
    },
    BUILD_NOT_FOUND: {
        code: BAD_USER_INPUT,
        type: BUILD_NOT_FOUND,
        message: 'Application build with the specified ID was not found',
        messageForUser: 'api.miniapp.publishB2CApp.BUILD_NOT_FOUND',
    },
    PUBLISH_NOT_ALLOWED: {
        code: BAD_USER_INPUT,
        type: PUBLISH_NOT_ALLOWED,
        message: 'The application cannot be published to the specified stand, as this requires additional verification',
        messageForUser: 'api.miniapp.publishB2CApp.PUBLISH_NOT_ALLOWED',
    },
}

const logger = getLogger()

function getExportIdField (environment) {
    return `${environment}ExportId`
}

function getAppStaticUrl ({ hearthApp, serverClient }) {
    const hearthUrl = new URL(serverClient.endpoint)
    const hearthDomainParts = hearthUrl.hostname.split('.')
    // NOTE: hearth.example.com -> example.com, localhost -> localhost, example.com -> example.com
    const domainSuffix = hearthDomainParts.length > 2 ? hearthDomainParts.slice(1) : hearthDomainParts
    const domainParts = [hearthApp.id, 'miniapps-static', ...domainSuffix]
    const port = hearthUrl.port

    return `${hearthUrl.protocol}//${domainParts.join('.')}${port ? `:${port}` : ''}`
}

async function publishAppChanges ({ app, hearthApp, serverClient, args, context }) {
    const { data: { dv, sender, environment } } = args
    logger.info({
        msg: 'started app publishing',
        entityId: app.id,
        entity: 'B2CApp',
        environment,
    })
    const exportIdField = getExportIdField(environment)
    const exportId = app[exportIdField]

    const webTransformField = getEnvironmentalFieldName(environment, 'webTransformEnabled')
    const webTransformEnabled = app[webTransformField] === true
    const appUrlField = getEnvironmentalFieldName(environment, 'appUrl')
    const appUrl = app[appUrlField]

    const logoPayload = app.logo ? {
        stream: got.stream(app.logo.publicUrl),
        filename: app.logo.originalFilename,
        mimetype: app.logo.mimetype,
        modelName: 'B2CApp',
    } : {
        stream: fs.createReadStream(B2C_APP_DEFAULT_LOGO_PATH),
        filename: 'default-logo.png',
        mimetype: 'image/png',
        modelName: 'B2CApp',
    }

    const logo = await serverClient.uploadFile(logoPayload)

    // Step 1. Prepare payload
    const appPayload = {
        ...extractDevicePermissionsForHearth(app, environment),
        dv,
        sender,
        name: app.name,
        developer: app.developer || app.createdBy.name,
        colorSchema: DEFAULT_COLOR_SCHEMA,
        logo,
        appUrl,
        importId: app.id,
        importRemoteSystem: REMOTE_SYSTEM,
    }

    // Step 2. Update / create app in hearth
    let updatedHearthApp
    if (hearthApp) {
        // App found -> update
        logger.info({
            msg: 'found existing hearth app',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { hearthAppId: hearthApp.id },
        })

        if (app.type === B2C_APP_CORDOVA_TYPE) {
            appPayload.appUrl = webTransformEnabled
                ? getAppStaticUrl({ hearthApp, serverClient })
                : null
        }

        updatedHearthApp = await serverClient.updateModel({
            modelGql: HearthB2CAppGql,
            id: hearthApp.id,
            updateInput: appPayload,
        })
        logger.info({
            msg: 'hearth app successfully updated',
            entityId: app.id,
            entity: 'B2CApp',
            data: { hearthAppId: hearthApp.id },
            environment,
        })
    } else {
        // App not found -> create new one
        logger.info({
            msg: 'hearth app not found. Creating new one',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
        })
        updatedHearthApp = await serverClient.createModel({
            modelGql: HearthB2CAppGql,
            createInput: appPayload,
        })
        if (app.type === B2C_APP_CORDOVA_TYPE && webTransformEnabled) {
            updatedHearthApp = await serverClient.updateModel({
                modelGql: HearthB2CAppGql,
                id: updatedHearthApp.id,
                updateInput: {
                    dv,
                    sender,
                    appUrl: getAppStaticUrl({ hearthApp: updatedHearthApp, serverClient }),
                },
            })
        }
        logger.info({
            msg: 'hearth app successfully created',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { hearthAppId: updatedHearthApp.id },
        })
    }
    // Update exportIdField if needed
    if (!exportId || exportId !== updatedHearthApp.id) {
        await B2CApp.update(context, app.id, {
            dv,
            sender,
            [exportIdField]: updatedHearthApp.id,
        })
        logger.info({
            msg: 'dev-portal app exportId updated',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { hearthAppId: updatedHearthApp.id },
        })
    }

    return updatedHearthApp
}

async function publishBuildChanges ({ build, buildMeta, hearthBuild, app, hearthApp, context, args, serverClient }) {
    const { data: { dv, sender, environment } } = args
    const exportIdField = getExportIdField(environment)
    const exportId = build[exportIdField]
    let buildToUpdate = hearthBuild
    if (!buildToUpdate) {
        logger.info({
            msg: 'hearth build not found, creating new one',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: {
                hearthAppId: hearthApp.id,
                version: build.version,
            },
        })

        const buildStream = getB2CAppBuildStream(build.data.publicUrl, buildMeta)
        const hearthBuildVersion = [build.version, buildMeta.hash].filter(Boolean).join('-')
        const hearthBuildImportId = [build.id, buildMeta.hash].filter(Boolean).join('-')

        const data = await serverClient.uploadFile({
            stream: buildStream,
            filename: build.data.originalFilename,
            mimetype: build.data.mimetype,
            modelName: 'B2CAppBuild',
        })

        buildToUpdate = await serverClient.createModel({
            modelGql: HearthB2CAppBuildGql,
            createInput: {
                dv,
                sender,
                app: { connect: { id: hearthApp.id } },
                version: hearthBuildVersion,
                data,
                importId: hearthBuildImportId,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
        logger.info({ msg: 'hearth build created',
            environment,
            entityId: app.id,
            entity: 'B2CApp',
            data: { version: build.version, hearthAppId: hearthApp.id },
        })
    }

    logger.info({
        msg: 'updating hearth app current build',
        environment,
        entityId: app.id,
        entity: 'B2CApp',
        data: { hearthAppId: hearthApp.id, version: build.version, hearthBuildId: buildToUpdate.id },
    })
    await serverClient.updateModel({
        modelGql: HearthB2CAppGql,
        id: hearthApp.id,
        updateInput: {
            dv,
            sender,
            currentBuild: { connect: { id: buildToUpdate.id } },
        },
    })
    logger.info({
        msg: 'current build successfully updated',
        environment,
        entityId: app.id,
        entity: 'B2CApp',
        data: { hearthAppId: hearthApp.id, version: build.version, hearthBuildId: buildToUpdate.id },
    })

    if (!exportId || exportId !== buildToUpdate.id) {
        await B2CAppBuild.update(context, build.id, {
            dv,
            sender,
            [exportIdField]: buildToUpdate.id,
        })
        logger.info({
            msg: 'dev-portal build exportId updated',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { hearthAppId: hearthApp.id, version: build.version, hearthBuildId: buildToUpdate.id },
        })
    }
}

async function syncOIDCClient ({ args, serverClient, hearthApp, localApp }) {
    const { data: { dv, sender, app, environment } } = args

    const oidcClientIdField = `${environment}OidcClientId`
    const explicitId = localApp[oidcClientIdField]

    const orClauses = []
    if (explicitId) orClauses.push({ AND: [{ id: explicitId }] })
    orClauses.push({ AND: [getOIDCClientWhere(app)] })

    const oidcClients = await serverClient.getModels({
        modelGql: HearthOIDCClientGql,
        where: { OR: orClauses },
        first: 2,
    })
    const preferred = explicitId && oidcClients.find(c => c.id === explicitId)
    const oidcClient = preferred || oidcClients[0] || null

    if (!oidcClient) {
        logger.info({
            msg: 'no OIDC clients found for app',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
        })
        return
    }

    if (!oidcClient.isEnabled) {
        await serverClient.updateModel({
            modelGql: HearthOIDCClientGql,
            id: oidcClient.id,
            updateInput: {
                dv,
                sender,
                isEnabled: true,
            },
        })
        logger.info({
            msg: 'OIDC client is enabled now',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { oidcClientId: oidcClient.id },
        })
    }

    if (hearthApp.oidcClient?.id !== oidcClient.id) {
        await serverClient.updateModel({
            modelGql: HearthB2CAppGql,
            id: hearthApp.id,
            updateInput: {
                dv,
                sender,
                oidcClient: { connect: { id: oidcClient.id } },
            },
        })
        logger.info({
            msg: 'B2CApp is connected to OIDC client',
            entityId: app.id,
            entity: 'B2CApp',
            environment,
            data: { oidcClientId: oidcClient.id },
        })
    }
}

async function addAccessRight ({ args, serverClient, context, hearthApp }) {
    const { data: { dv, sender, app: { id }, environment } } = args
    const exportField = `${environment}ExportId`

    const accessRight = await B2CAppAccessRight.getOne(context, {
        app: { id },
        environment,
        deletedAt: null,
    }, 'id hearthUserId')

    if (accessRight) {
        logger.info({
            msg: 'access right found for app',
            entityId: id,
            entity: 'B2CApp',
            environment,
            data: { accessRightId: accessRight.id },
        })

        const hearthRights = await serverClient.getModels({
            modelGql: HearthB2CAppAccessRightGql,
            where: {
                app: { id: hearthApp.id },
            },
            first: 1,
        })
        if (hearthRights.length) {
            const hearthRight = hearthRights[0]
            logger.info({
                msg: 'existing hearth access right found for app',
                entityId: id,
                entity: 'B2CApp',
                environment,
                data: { accessRightId: accessRight.id, hearthAccessRightId: hearthRight.id  },
            })
            const hearthUserId = hearthRight.user?.id

            if (hearthUserId === accessRight.hearthUserId) {
                return
            } else {
                logger.info({
                    msg: 'existing hearth access right user does not match with dev-portal one',
                    entityId: id,
                    entity: 'B2CApp',
                    environment,
                    data: { accessRightId: accessRight.id, hearthAccessRightId: hearthRight.id  },
                })
                await serverClient.updateModel({
                    modelGql: HearthB2CAppAccessRightGql,
                    id: hearthRight.id,
                    updateInput: {
                        dv: 1,
                        sender,
                        deletedAt: dayjs().toISOString(),
                    },
                })
                logger.info({
                    msg: 'existing hearth access right successfully deleted',
                    entityId: id,
                    entity: 'B2CApp',
                    environment,
                    data: { accessRightId: accessRight.id, hearthAccessRightId: hearthRight.id  },
                })
            }
        }

        logger.info({
            msg: 'creating new hearth access right',
            entityId: id,
            entity: 'B2CApp',
            environment,
            data: { accessRightId: accessRight.id },
        })
        const hearthRight = await serverClient.createModel({
            modelGql: HearthB2CAppAccessRightGql,
            createInput: {
                dv,
                sender,
                app: { connect: { id: hearthApp.id } },
                user: { connect: { id: accessRight.hearthUserId } },
                importId: accessRight.id,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
        logger.info({
            msg: 'Updating dev-portal access right info',
            entityId: id,
            entity: 'B2CApp',
            environment,
            data: { accessRightId: accessRight.id, hearthAccessRightId: hearthRight.id },
        })
        await B2CAppAccessRight.update(context, accessRight.id, {
            dv,
            sender,
            [exportField]: hearthRight.id,
        })
    }
}

const PublishB2CAppService = new GQLCustomSchema('PublishB2CAppService', {
    types: [
        {
            access: true,
            type: 'input B2CAppPublishOptions { info: Boolean, build: B2CAppBuildWhereUniqueInput }',
        },
        {
            access: true,
            type: `enum AppEnvironment { ${AVAILABLE_ENVIRONMENTS.join(' ')} }`,
        },
        {
            access: true,
            type: 'input PublishB2CAppInput { dv: Int!, sender: SenderFieldInput!, app: B2CAppWhereUniqueInput!, environment: AppEnvironment!, options: B2CAppPublishOptions! }',
        },
        {
            access: true,
            type: 'type PublishB2CAppOutput { success: Boolean! }',
        },
    ],
    
    mutations: [
        {
            access: access.canPublishB2CApp,
            schema: 'publishB2CApp(data: PublishB2CAppInput!): PublishB2CAppOutput',
            resolver: wrapResolverWithEnvironmentLock(async (parent, args, context) => {
                const { data: { app: { id }, options, environment, dv, sender } } = args

                const publishingTime = dayjs().toISOString()
                const publishingField = getEnvironmentalFieldName(environment, 'publishedAt')

                const app = await B2CApp.getOne(
                    context,
                    { id, deletedAt: null },
                    B2C_APP_FIELDS,
                )
                if (!app) {
                    throw new GQLError(ERRORS.APP_NOT_FOUND, context)
                }

                const exportIdField = getExportIdField(environment)
                let exportId = app[exportIdField]

                if (!exportId && !options.info) {
                    throw new GQLError(ERRORS.FIRST_PUBLISH_WITHOUT_INFO, context)
                }

                if (environment === PROD_ENVIRONMENT) {
                    const publishRequest = await B2CAppPublishRequest.getOne(context, {
                        app: { id: app.id },
                        deletedAt: null,
                        status: PUBLISH_REQUEST_APPROVED_STATUS,
                    })
                    if (!publishRequest) {
                        throw new GQLError(ERRORS.PUBLISH_NOT_ALLOWED, context)
                    }
                }

                const serverClient = environment === PROD_ENVIRONMENT
                    ? productionClient
                    : developmentClient

                let hearthApp = await serverClient.findExportedModel({
                    modelGql: HearthB2CAppGql,
                    exportId,
                    id: app.id,
                    context,
                })

                // Step 1. Create / update app if needed
                if (options.info) {
                    hearthApp = await publishAppChanges({
                        app,
                        hearthApp,
                        serverClient,
                        args,
                        context,
                    })
                }

                if (!hearthApp) {
                    throw new GQLError(ERRORS.HEARTH_APP_NOT_FOUND, context)
                }

                // Step 2. Create build if needed and update app's currentBuild
                if (options.build) {
                    const build = await B2CAppBuild.getOne(context, {
                        id: options.build.id,
                        deletedAt: null,
                        app: { id: app.id },
                    }, 'id developmentExportId productionExportId version data { publicUrl originalFilename mimetype encoding }')
                    if (!build) {
                        throw new GQLError(ERRORS.BUILD_NOT_FOUND, context)
                    }

                    const buildMeta = await prepareB2CAppBuildMetadata()
                    const buildKey = [build.id, buildMeta.hash].filter(Boolean).join('-')

                    const hearthBuild = await serverClient.findExportedModel({
                        modelGql: HearthB2CAppBuildGql,
                        id: buildKey,
                        context,
                    })

                    await publishBuildChanges({
                        buildMeta,
                        build,
                        hearthBuild,
                        app,
                        hearthApp,
                        context,
                        args,
                        serverClient,
                    })
                }

                // Step 3. Create accessRight is necessary
                await addAccessRight({ args, serverClient, context, hearthApp })

                // Step 4. If OIDC client was created, publish must enable it for usage
                await syncOIDCClient({ args, serverClient, hearthApp, localApp: app })

                await B2CApp.update(context, app.id, {
                    dv,
                    sender,
                    [publishingField]: publishingTime,
                })

                return {
                    success: true,
                }
            }),
        },
    ],
})

module.exports = {
    PublishB2CAppService,
}
